timeout 10 base64 -d "$root/software_payload.b64" > "$root/software_payload.tar.gz"
printf '%s  %s\n' 9ad0f51bdbcea592d95660ea1d711ee318bc52b72488e74d0c7fe2e104a81527 "$root/software_payload.tar.gz" | timeout 10 sha256sum --check --status
timeout 15 tar --no-same-owner --no-same-permissions -xzf "$root/software_payload.tar.gz" -C "$root"
printf 'SOFTWARE_PAYLOAD_VERIFIED_SHA256=%s\n' 9ad0f51bdbcea592d95660ea1d711ee318bc52b72488e74d0c7fe2e104a81527
test -f "$root/remote/synthetic_gpu_probe.sbatch"
test ! -e "$root/reports/SUBMISSION_ATTEMPTED"
set -C
date -u '+%Y-%m-%dT%H:%M:%SZ' > "$root/reports/SUBMISSION_ATTEMPTED"
submission_exit=0
timeout 20 sbatch "$root/remote/synthetic_gpu_probe.sbatch" > "$root/reports/sbatch.stdout" 2> "$root/reports/sbatch.stderr" || submission_exit=$?
printf 'SBATCH_PROCESS_EXIT=%s\n' "$submission_exit"
cat "$root/reports/sbatch.stdout"
cat "$root/reports/sbatch.stderr"
marker_count=$(awk '/^Submitted batch job [0-9]+$/ {n++} END {print n+0}' "$root/reports/sbatch.stdout")
if test "$submission_exit" -ne 0 || test "$marker_count" -ne 1; then
    printf 'SUBMISSION_FAILED_OR_UNCERTAIN_NO_RETRY\n'
    exit 74
fi
job_id=$(awk '/^Submitted batch job [0-9]+$/ {print $4}' "$root/reports/sbatch.stdout")
printf '%s\n' "$job_id" > "$root/reports/OWN_JOB_ID.txt"
printf 'OWN_SYNTHETIC_GPU_JOB_ID=%s\n' "$job_id"
printf 'ISOLATED_SYNTHETIC_PROBE_SUBMITTED\n'
